--
-- Table structure for table `education`
--

DROP TABLE IF EXISTS `education`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `education` (
  `education_id` int NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL,
  `school_name` varchar(100) NOT NULL,
  `degree` enum('ASSOCIATE','DIPLOMA','BACHELOR','MASTER','MBA','PHD') NOT NULL,
  `field_of_study` varchar(80) NOT NULL,
  `start_year` smallint NOT NULL,
  `end_year` smallint DEFAULT NULL,
  PRIMARY KEY (`education_id`),
  KEY `idx_edu_member` (`member_id`),
  CONSTRAINT `fk_edu_member` FOREIGN KEY (`member_id`) REFERENCES `member` (`member_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ck_edu_years` CHECK (((`start_year` between 1950 and 2026) and ((`end_year` is null) or ((`end_year` >= `start_year`) and (`end_year` <= 2030)))))
) ENGINE=InnoDB AUTO_INCREMENT=394 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

