--
-- Table structure for table `experience`
--

DROP TABLE IF EXISTS `experience`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `experience` (
  `experience_id` int NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL,
  `company_id` int NOT NULL,
  `title` varchar(100) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date DEFAULT NULL,
  `is_current` tinyint(1) NOT NULL DEFAULT '0',
  `current_member_id` int GENERATED ALWAYS AS (if((`is_current` = 1),`member_id`,NULL)) VIRTUAL,
  PRIMARY KEY (`experience_id`),
  UNIQUE KEY `uk_exp_one_current` (`current_member_id`),
  KEY `idx_exp_member` (`member_id`,`is_current`),
  KEY `idx_exp_company` (`company_id`,`is_current`),
  CONSTRAINT `fk_exp_company` FOREIGN KEY (`company_id`) REFERENCES `company` (`company_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_exp_member` FOREIGN KEY (`member_id`) REFERENCES `member` (`member_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `ck_exp_current` CHECK ((`is_current` in (0,1))),
  CONSTRAINT `ck_exp_current_open` CHECK ((((`is_current` = 1) and (`end_date` is null)) or ((`is_current` = 0) and (`end_date` is not null)))),
  CONSTRAINT `ck_exp_dates` CHECK (((`end_date` is null) or (`end_date` >= `start_date`)))
) ENGINE=InnoDB AUTO_INCREMENT=493 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

