--
-- Table structure for table `job_skill`
--

DROP TABLE IF EXISTS `job_skill`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `job_skill` (
  `job_id` int NOT NULL,
  `skill_id` int NOT NULL,
  `importance` enum('REQUIRED','PREFERRED') NOT NULL DEFAULT 'REQUIRED',
  `min_proficiency` tinyint NOT NULL DEFAULT '3',
  PRIMARY KEY (`job_id`,`skill_id`),
  KEY `idx_js_skill` (`skill_id`,`importance`),
  CONSTRAINT `fk_js_job` FOREIGN KEY (`job_id`) REFERENCES `job_posting` (`job_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_js_skill` FOREIGN KEY (`skill_id`) REFERENCES `skill` (`skill_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ck_js_proficiency` CHECK ((`min_proficiency` between 1 and 5))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

